@startuml

class School {
  + name : string
}

class Person {
  + firstName : string
  + lastName : string
}

class Teacher extends Person {
  + email : string
}

class Student extends Person {
}

class TeachingAssignment {
  + hours : int
}

class Room {
}

class Classroom extends Room {
  + name : string
  + capacity : int
}

class Gym extends Room {
  + name : string
  + size : float
}

class ClassGroup {
  + name : string
}

School "1" -- "1" Teacher : principal
School "1" -- "*" Teacher : employs
Teacher "0..3" -- "*" School : teaches
TeachingAssignment "*" -- "1" Teacher
TeachingAssignment "*" -- "1" School

School "1" -- "*" Room

Classroom "1" -- "1" ClassGroup
ClassGroup "1" -- "1" Classroom

ClassGroup "1" -- "10..31" Student

@enduml

